import{c as e,Q as s,j as i,m as t}from"./chunks/framework.8JjYC3xy.js";const u=JSON.parse('{"title":"第六章：编辑和创建代码","description":"学会让 Claude 直接帮你写代码、修改代码","frontmatter":{"title":"第六章：编辑和创建代码","description":"学会让 Claude 直接帮你写代码、修改代码"},"headers":[],"relativePath":"guide/2-basic-usage/6-edit-code.md","filePath":"guide/2-basic-usage/6-edit-code.md"}'),l={name:"guide/2-basic-usage/6-edit-code.md"};function n(o,a,d,p,r,c){return s(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="第六章-编辑和创建代码" tabindex="-1">第六章：编辑和创建代码 <a class="header-anchor" href="#第六章-编辑和创建代码" aria-label="Permalink to &quot;第六章：编辑和创建代码&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">学习目标</p><p>学完这章，你会让 Claude 帮你创建新文件和修改现有文件，掌握安全编辑的技巧。</p></div><h2 id="两种编辑方式" tabindex="-1">两种编辑方式 <a class="header-anchor" href="#两种编辑方式" aria-label="Permalink to &quot;两种编辑方式&quot;">​</a></h2><ol><li><strong>直接生成</strong>：让 Claude 写完整代码，你复制使用</li><li><strong>直接修改</strong>：描述要改什么，Claude 直接修改你的文件</li></ol><h2 id="创建新文件" tabindex="-1">创建新文件 <a class="header-anchor" href="#创建新文件" aria-label="Permalink to &quot;创建新文件&quot;">​</a></h2><h3 id="直接描述需求" tabindex="-1">直接描述需求 <a class="header-anchor" href="#直接描述需求" aria-label="Permalink to &quot;直接描述需求&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我创建一个 sum.py，实现加法函数</span></span></code></pre></div><p>Claude 会给你完整的代码。</p><h3 id="复制使用" tabindex="-1">复制使用 <a class="header-anchor" href="#复制使用" aria-label="Permalink to &quot;复制使用&quot;">​</a></h3><p>把代码复制到你的编辑器，保存文件。</p><h2 id="修改现有文件" tabindex="-1">修改现有文件 <a class="header-anchor" href="#修改现有文件" aria-label="Permalink to &quot;修改现有文件&quot;">​</a></h2><p>Claude Code 没有专门的编辑命令。正确的做法是：<strong>直接描述你想怎么改</strong>。</p><h3 id="描述你要改什么" tabindex="-1">描述你要改什么 <a class="header-anchor" href="#描述你要改什么" aria-label="Permalink to &quot;描述你要改什么&quot;">​</a></h3><p>不需要记住任何命令，直接说人话：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把这个函数的返回值从 int 改成 float</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我把 auth.py 里的密码加密换成 bcrypt</span></span></code></pre></div><h3 id="claude-会做什么" tabindex="-1">Claude 会做什么 <a class="header-anchor" href="#claude-会做什么" aria-label="Permalink to &quot;Claude 会做什么&quot;">​</a></h3><ol><li>分析你的代码</li><li>生成修改后的代码（展示 diff）</li><li>等待你确认</li></ol><h3 id="确认或拒绝" tabindex="-1">确认或拒绝 <a class="header-anchor" href="#确认或拒绝" aria-label="Permalink to &quot;确认或拒绝&quot;">​</a></h3><ul><li><strong>approve</strong>：Claude 写入文件</li><li><strong>deny</strong>：Claude 停止，等待你换一种描述方式</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>好，改吧        → approve</span></span>\n<span class="line"><span>不用这个方案    → deny，换一种说法</span></span></code></pre></div><h2 id="与编辑创建相关的命令" tabindex="-1">与编辑创建相关的命令 <a class="header-anchor" href="#与编辑创建相关的命令" aria-label="Permalink to &quot;与编辑创建相关的命令&quot;">​</a></h2><p>Claude Code 的斜杠命令已统一合并到 Skills 体系中。以下命令在编辑创建场景中最有用：</p><h3 id="init-—-初始化项目" tabindex="-1"><code>/init</code> — 初始化项目 <a class="header-anchor" href="#init-—-初始化项目" aria-label="Permalink to &quot;`/init` — 初始化项目&quot;">​</a></h3><p>让 Claude 扫描当前代码库，生成 CLAUDE.md 项目规范文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/init</span></span></code></pre></div><p><strong>什么时候用</strong>：接手一个新项目后，先跑一下 <code>/init</code>，Claude 会分析代码结构并生成文档。</p><h3 id="plan-—-先规划再执行" tabindex="-1"><code>/plan</code> — 先规划再执行 <a class="header-anchor" href="#plan-—-先规划再执行" aria-label="Permalink to &quot;`/plan` — 先规划再执行&quot;">​</a></h3><p>让 Claude 先分析代码，生成详细的修改计划，<strong>等你确认后再执行</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/plan</span></span>\n<span class="line"><span>帮我把 auth 模块的 session 改成 JWT</span></span></code></pre></div><p>Claude 会：</p><ol><li>分析现有代码结构</li><li>生成修改步骤</li><li>等待你确认后才真正动手</li></ol><p><strong>什么时候用</strong>：大改动、不确定风险时，用 <code>/plan</code> 更安全。</p><h3 id="review-—-代码审查" tabindex="-1"><code>/review</code> — 代码审查 <a class="header-anchor" href="#review-—-代码审查" aria-label="Permalink to &quot;`/review` — 代码审查&quot;">​</a></h3><p>对代码进行全面审查，发现潜在 bug 和优化点：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/review</span></span></code></pre></div><p><strong>什么时候用</strong>：写完一段代码后，让 Claude 过一遍，比自己检查更客观。</p><h2 id="撤销与回退" tabindex="-1">撤销与回退 <a class="header-anchor" href="#撤销与回退" aria-label="Permalink to &quot;撤销与回退&quot;">​</a></h2><h3 id="rewind-—-回退到之前的状态" tabindex="-1"><code>/rewind</code> — 回退到之前的状态 <a class="header-anchor" href="#rewind-—-回退到之前的状态" aria-label="Permalink to &quot;`/rewind` — 回退到之前的状态&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/rewind</span></span></code></pre></div><p><strong><code>/rewind</code> 会同时回退两件事：</strong></p><ol><li><strong>对话历史</strong> — 回到之前的某个对话节点</li><li><strong>文件状态</strong> — 文件也会恢复到那个节点的样子</li></ol><p>如果改坏了文件，直接 <code>/rewind</code> 就能一起退回去，比从 Git 逐个还原更方便。</p><h2 id="批量编辑" tabindex="-1">批量编辑 <a class="header-anchor" href="#批量编辑" aria-label="Permalink to &quot;批量编辑&quot;">​</a></h2><h3 id="一次性修改多个文件" tabindex="-1">一次性修改多个文件 <a class="header-anchor" href="#一次性修改多个文件" aria-label="Permalink to &quot;一次性修改多个文件&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我重构 auth 模块：</span></span>\n<span class="line"><span>1. User 模型添加 email 字段</span></span>\n<span class="line"><span>2. login 函数改用 bcrypt 加密</span></span>\n<span class="line"><span>3. 更新相关测试</span></span></code></pre></div><h3 id="编辑后验证" tabindex="-1">编辑后验证 <a class="header-anchor" href="#编辑后验证" aria-label="Permalink to &quot;编辑后验证&quot;">​</a></h3><p>编辑完成后，让 Claude 检查：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我检查一下修改是否正确，有没有引入新问题</span></span></code></pre></div><h2 id="一定要审查代码" tabindex="-1">一定要审查代码！ <a class="header-anchor" href="#一定要审查代码" aria-label="Permalink to &quot;一定要审查代码！&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">重要</p><p>Claude 写的代码一定要看一遍再使用！</p></div><p>Claude 可能：</p><ul><li>有 bug</li><li>不符合你的编码习惯</li><li>有安全风险</li></ul><p>你是最后把关的人。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q: Claude 写的代码报错？</strong></p><p>A: 把错误信息粘贴给 Claude，让它修复。</p><p><strong>Q: 不想用 Claude 写的？</strong></p><p>A: 直接说&quot;不要这个方案，换一个&quot;。</p><p><strong>Q: 怎么只接受部分修改？</strong></p><p>A: 可以手动微调，Claude 不会介意。</p><p><strong>Q: 如何回退到之前的版本？</strong></p><p>A: 使用 <code>/rewind</code> 回退对话和文件到之前状态，或从 Git 恢复文件。</p><p><strong>Q: Claude 会覆盖我手动改的文件吗？</strong></p><p>A: 不会，Claude 只在你明确批准后才会写入文件。</p><p><strong>Q: 能查看文件编辑历史吗？</strong></p><p>A: 通过 Git 可以查看，Claude 的每次编辑都对应一个 commit。</p><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><ol><li>让 Claude 帮你写一个&quot;学生成绩管理&quot;程序</li><li>让它添加&quot;添加学生&quot;和&quot;查看成绩&quot;功能</li><li>对代码运行 <code>/review</code>，看看 Claude 发现了什么问题</li><li>用 <code>/rewind</code> 体验一下回退效果</li></ol><h2 id="下一章" tabindex="-1">下一章 <a class="header-anchor" href="#下一章" aria-label="Permalink to &quot;下一章&quot;">​</a></h2><p>下一章我们会学习如何通过多轮对话完善代码。</p><p><a href="/claude-code-guide/guide/2-basic-usage/7-multi-turn.html">👉 第七章：多轮对话技巧</a></p>',72)])])}const g=e(l,[["render",n]]);export{u as __pageData,g as default};
